"use client";

import { LoaderCircle, X } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";

import { AgentDisclosure } from "@/components/agents/agent-disclosure";
import { Button } from "@/components/motion/button";
import { Input } from "@/components/motion/input";
import { RadioGroup, RadioGroupItem } from "@/components/motion/radio";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { EASE_OUT, SPRING_SWAP } from "@/lib/ease";
import { cn } from "@/lib/utils";

import type {
  ApprovalCardAnswer,
  ApprovalCardAnswers,
  ApprovalCardProps,
  ApprovalCardQuestion,
  ApprovalCardStatus,
} from "./types";

export type {
  ApprovalCardAnswer,
  ApprovalCardAnswers,
  ApprovalCardOption,
  ApprovalCardProps,
  ApprovalCardQuestion,
  ApprovalCardStatus,
} from "./types";

const EMPTY_ANSWER: ApprovalCardAnswer = { custom: "", selected: [] };

const STATUS_LABEL: Record<ApprovalCardStatus, string> = {
  answered: "Response submitted",
  approved: "Approved",
  "changes-requested": "Changes requested",
  pending: "Input required",
  rejected: "Rejected",
  submitting: "Submitting",
};

const getStatusLabel = (status: ApprovalCardStatus) => STATUS_LABEL[status];

function isAnswered(answer: ApprovalCardAnswer) {
  return answer.selected.length > 0 || Boolean(answer.custom?.trim());
}

function QuestionOptions({
  question,
  answer,
  disabled,
  onChange,
  onAutoAdvance,
}: {
  question: ApprovalCardQuestion;
  answer: ApprovalCardAnswer;
  disabled: boolean;
  onChange: (answer: ApprovalCardAnswer) => void;
  onAutoAdvance?: () => void;
}) {
  const custom = answer.custom ?? "";

  return (
    <div className="mt-3">
      {question.options?.length ? (
        <RadioGroup
          value={answer.selected[0] ?? ""}
          onValueChange={(value) => {
            onChange({ custom: "", selected: [value] });
            onAutoAdvance?.();
          }}
          className="gap-0.5"
        >
          {question.options.map((option) => (
            <RadioGroupItem
              key={option.value}
              value={option.value}
              label={option.label}
              disabled={disabled || option.disabled}
              className="min-h-9 rounded-lg px-1.5 py-1"
            />
          ))}
        </RadioGroup>
      ) : null}

      <Input
        value={custom}
        disabled={disabled}
        placeholder={question.customPlaceholder ?? "Add another response…"}
        onChange={(value) => onChange({ custom: value, selected: [] })}
        className={cn("p-0.5", question.options?.length && "mt-1.5")}
        classNames={{
          field:
            "h-10 rounded-xl border-0 bg-background/70 focus-within:bg-background",
          input: "px-3 text-sm",
        }}
      />
    </div>
  );
}

// One bar per question — and the only step control on the left. Width carries position
// (the current bar is twice the resting width), colour carries the answer state, and
// clicking jumps. Bars are sized by their content, so hovering one grows it and pushes
// the rest of the row right instead of eating the gap to its neighbour. Widths stay real
// (never `scaleX`), so the pill caps stay round.
const BAR_REST_WIDTH = 8;
const BAR_CURRENT_WIDTH = 16;
const BAR_HOVER_WIDTH = 20;

function barTone({
  answered,
  current,
  hovered,
  skipped,
}: {
  answered: boolean;
  current: boolean;
  hovered: boolean;
  skipped: boolean;
}) {
  if (skipped) {
    return "bg-warning";
  }
  if (current) {
    return "bg-foreground";
  }
  if (hovered) {
    return answered ? "bg-foreground" : "bg-foreground/45";
  }
  return answered ? "bg-foreground/55" : "bg-foreground/20";
}

function StepBars({
  current,
  questions,
  answers,
  onSelect,
}: {
  current: number;
  questions: ApprovalCardQuestion[];
  answers: ApprovalCardAnswers;
  onSelect: (index: number) => void;
}) {
  const reduce = useReducedMotion() ?? false;
  const [hovered, setHovered] = useState<string | null>(null);

  return (
    <span className="flex items-center gap-1.5">
      {questions.map((question, index) => {
        const answered = isAnswered(answers[question.id] ?? EMPTY_ANSWER);
        const skipped = index < current && !answered;
        const label =
          typeof question.title === "string"
            ? question.title
            : `Question ${index + 1}`;
        const width =
          hovered === question.id && !reduce
            ? BAR_HOVER_WIDTH
            : index === current
              ? BAR_CURRENT_WIDTH
              : BAR_REST_WIDTH;

        return (
          <Tooltip key={question.id}>
            <TooltipTrigger asChild>
              <button
                type="button"
                aria-label={`Question ${index + 1} of ${questions.length}: ${label}${
                  answered ? " (answered)" : skipped ? " (unanswered)" : ""
                }`}
                aria-current={index === current ? "step" : undefined}
                onClick={() => onSelect(index)}
                onPointerEnter={() => setHovered(question.id)}
                onPointerLeave={() => setHovered(null)}
                onFocus={() => setHovered(question.id)}
                onBlur={() => setHovered(null)}
                className="flex h-4 cursor-pointer items-center rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <motion.span
                  initial={false}
                  animate={{ width }}
                  transition={reduce ? { duration: 0 } : SPRING_SWAP}
                  className={cn(
                    "h-1 rounded-full transition-colors duration-200",
                    barTone({
                      answered,
                      current: index === current,
                      hovered: hovered === question.id && !reduce,
                      skipped,
                    })
                  )}
                />
              </button>
            </TooltipTrigger>
            <TooltipContent className="max-w-none whitespace-nowrap">
              {question.title}
            </TooltipContent>
          </Tooltip>
        );
      })}
    </span>
  );
}

export function ApprovalCard({
  title = "Approval required",
  description,
  children,
  questions = [],
  status = "pending",
  answers,
  defaultAnswers = {},
  onAnswersChange,
  step,
  defaultStep = 0,
  onStepChange,
  onSubmit,
  onApprove,
  onReject,
  onRequestChanges,
  onDismiss,
  approveLabel = "Approve",
  submitLabel = "Submit",
  continueLabel = "Continue",
  skipLabel = "Skip",
  result,
  className,
}: ApprovalCardProps) {
  const reduce = useReducedMotion() ?? false;
  const [internalAnswers, setInternalAnswers] =
    useState<ApprovalCardAnswers>(defaultAnswers);
  const [internalStep, setInternalStep] = useState(defaultStep);
  const autoAdvanceTimer = useRef<number | null>(null);
  // Which way the last step change went, so the question slides in from the side
  // the user is travelling towards. Read during render, written after paint.
  const previousStep = useRef(defaultStep);
  const currentAnswers = answers ?? internalAnswers;
  const currentStep = Math.min(
    Math.max(0, step ?? internalStep),
    Math.max(0, questions.length - 1)
  );
  const question = questions[currentStep];
  const questionMode = questions.length > 0;
  const pending = status === "pending";
  const busy = status === "submitting";
  const interactive = pending || busy;
  const currentAnswer = question
    ? (currentAnswers[question.id] ?? EMPTY_ANSWER)
    : EMPTY_ANSWER;
  const displayTitle = question?.title ?? title;
  const statusLabel = getStatusLabel(status);
  const lastStep = currentStep === questions.length - 1;
  // One read-out per question: solid = answered, amber = walked past without an
  // answer, faint = not reached yet. The counter keeps the summary warning; this is
  // what makes "which one is missing" visible without counting.
  const answeredCount = questions.filter((item) =>
    isAnswered(currentAnswers[item.id] ?? EMPTY_ANSWER)
  ).length;
  const allAnswered = answeredCount === questions.length;
  const slide =
    reduce || currentStep === previousStep.current
      ? 0
      : currentStep > previousStep.current
        ? 1
        : -1;

  const clearAutoAdvance = useCallback(() => {
    if (autoAdvanceTimer.current === null) {
      return;
    }
    window.clearTimeout(autoAdvanceTimer.current);
    autoAdvanceTimer.current = null;
  }, []);

  useEffect(() => clearAutoAdvance, [clearAutoAdvance]);

  useEffect(() => {
    previousStep.current = currentStep;
  }, [currentStep]);

  const setAnswers = useCallback(
    (next: ApprovalCardAnswers) => {
      if (answers === undefined) {
        setInternalAnswers(next);
      }
      onAnswersChange?.(next);
    },
    [answers, onAnswersChange]
  );

  const setStep = (next: number) => {
    clearAutoAdvance();
    if (step === undefined) {
      setInternalStep(next);
    }
    onStepChange?.(next);
  };

  const updateCurrentAnswer = (next: ApprovalCardAnswer) => {
    if (!question) {
      return;
    }
    setAnswers({ ...currentAnswers, [question.id]: next });
  };

  const continueQuestion = () => {
    if (currentStep < questions.length - 1) {
      setStep(currentStep + 1);
      return;
    }
    onSubmit?.(currentAnswers);
  };

  const queueAutoAdvance = () => {
    if (
      !question ||
      question.autoAdvance === false ||
      currentStep >= questions.length - 1 ||
      busy
    ) {
      return;
    }

    clearAutoAdvance();
    autoAdvanceTimer.current = window.setTimeout(() => {
      setStep(currentStep + 1);
    }, 240);
  };

  return (
    <div
      data-state={status}
      aria-busy={busy}
      className={cn(
        "w-full overflow-hidden rounded-2xl bg-muted p-4 text-sm",
        className
      )}
    >
      <div className="min-w-0">
        <div className="flex min-w-0 items-start gap-3">
          <h3 className="min-w-0 flex-1 text-base font-medium leading-5 text-foreground">
            {displayTitle}
          </h3>
          {onDismiss ? (
            <button
              type="button"
              aria-label="Dismiss"
              onClick={onDismiss}
              className="grid size-5 shrink-0 place-items-center rounded-full text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
            >
              <X className="size-4" />
            </button>
          ) : null}
        </div>

        <AgentDisclosure open={interactive}>
          {questionMode && question ? (
            <motion.div
              key={question.id}
              initial={{ opacity: 0, x: 8 * slide }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.18, ease: EASE_OUT }}
            >
              {question.description ? (
                <p className="mt-1 leading-5 text-muted-foreground">
                  {question.description}
                </p>
              ) : null}
              <QuestionOptions
                question={question}
                answer={currentAnswer}
                disabled={busy}
                onChange={updateCurrentAnswer}
                onAutoAdvance={queueAutoAdvance}
              />
            </motion.div>
          ) : (
            <div>
              {description ? (
                <p className="mt-1 leading-5 text-muted-foreground">
                  {description}
                </p>
              ) : null}
              {children ? <div className="mt-3">{children}</div> : null}
            </div>
          )}

          {questionMode ? (
            <div className="mt-4 flex items-center gap-3">
              <StepBars
                answers={currentAnswers}
                current={currentStep}
                onSelect={setStep}
                questions={questions}
              />
              <div className="ml-auto flex items-center gap-2">
                {lastStep ? null : (
                  <Button
                    variant="secondary"
                    size="sm"
                    disabled={busy}
                    onClick={() => setStep(currentStep + 1)}
                  >
                    {skipLabel}
                  </Button>
                )}
                <Button
                  size="sm"
                  disabled={busy || (lastStep && !allAnswered)}
                  onClick={continueQuestion}
                >
                  {busy ? (
                    <LoaderCircle
                      className={cn("size-4", !reduce && "animate-spin")}
                    />
                  ) : lastStep ? (
                    submitLabel
                  ) : (
                    continueLabel
                  )}
                </Button>
              </div>
            </div>
          ) : (
            <div className="mt-4 flex flex-wrap items-center gap-2">
              <Button
                size="sm"
                disabled={busy}
                onClick={onApprove}
                className="rounded-full"
              >
                {approveLabel}
              </Button>
              {onRequestChanges ? (
                <Button
                  variant="secondary"
                  size="sm"
                  disabled={busy}
                  onClick={onRequestChanges}
                  className="rounded-full"
                >
                  Request changes
                </Button>
              ) : null}
              {onReject ? (
                <Button
                  variant="ghost"
                  size="sm"
                  disabled={busy}
                  onClick={onReject}
                  className="rounded-full text-muted-foreground hover:text-destructive"
                >
                  Reject
                </Button>
              ) : null}
            </div>
          )}
        </AgentDisclosure>

        {!interactive ? (
          <p className="mt-1 text-sm text-muted-foreground">
            {result ?? statusLabel}
          </p>
        ) : null}
      </div>
    </div>
  );
}

import type { ReactNode } from "react";

export type ApprovalCardStatus =
  | "pending"
  | "submitting"
  | "approved"
  | "rejected"
  | "changes-requested"
  | "answered";

export interface ApprovalCardOption {
  value: string;
  label: string;
  disabled?: boolean;
}

export interface ApprovalCardQuestion {
  id: string;
  title: ReactNode;
  description?: ReactNode;
  options?: ApprovalCardOption[];
  autoAdvance?: boolean;
  customPlaceholder?: string;
}

export interface ApprovalCardAnswer {
  selected: string[];
  custom?: string;
}

export type ApprovalCardAnswers = Record<string, ApprovalCardAnswer>;

export interface ApprovalCardProps {
  title?: ReactNode;
  description?: ReactNode;
  children?: ReactNode;
  questions?: ApprovalCardQuestion[];
  status?: ApprovalCardStatus;
  answers?: ApprovalCardAnswers;
  defaultAnswers?: ApprovalCardAnswers;
  onAnswersChange?: (answers: ApprovalCardAnswers) => void;
  step?: number;
  defaultStep?: number;
  onStepChange?: (step: number) => void;
  onSubmit?: (answers: ApprovalCardAnswers) => void;
  onApprove?: () => void;
  onReject?: () => void;
  onRequestChanges?: () => void;
  onDismiss?: () => void;
  approveLabel?: ReactNode;
  submitLabel?: ReactNode;
  continueLabel?: ReactNode;
  skipLabel?: ReactNode;
  result?: ReactNode;
  className?: string;
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import type { HTMLMotionProps } from "motion/react";
import type { CSSProperties } from "react";

import { EASE_OUT } from "@/lib/ease";
import { cn } from "@/lib/utils";

export interface AgentDisclosureProps extends Omit<
  HTMLMotionProps<"div">,
  "animate" | "initial"
> {
  open: boolean;
  openHeight?: CSSProperties["height"];
}

/** Shared transform-only reveal for collapsible agent content. */
export function AgentDisclosure({
  open,
  openHeight = "auto",
  className,
  style,
  transition,
  ...props
}: AgentDisclosureProps) {
  const reduce = useReducedMotion() ?? false;

  return (
    <motion.div
      {...props}
      aria-hidden={!open}
      inert={!open}
      initial={false}
      animate={
        reduce
          ? { opacity: open ? 1 : 0 }
          : {
              clipPath: open ? "inset(0 0 0% 0)" : "inset(0 0 100% 0)",
              opacity: open ? 1 : 0,
              y: open ? 0 : -4,
            }
      }
      transition={
        transition ?? {
          duration: reduce ? 0 : open ? 0.22 : 0.14,
          ease: EASE_OUT,
        }
      }
      className={cn("overflow-hidden", className)}
      style={{
        ...style,
        height: open ? openHeight : 0,
        pointerEvents: open ? undefined : "none",
        transformOrigin: "top",
      }}
    />
  );
}

export type {
  ButtonLinkProps,
  ButtonProps,
  ButtonSize,
  ButtonVariant,
} from "./base";
export { Button, ButtonLink } from "./base";

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { HTMLMotionProps } from "motion/react";
import { forwardRef, useCallback, useRef, useState } from "react";
import type { PointerEvent, ReactNode } from "react";

import { EASE_OUT, SPRING_PRESS } from "@/lib/ease";
import { useHoverCapable } from "@/lib/hooks/use-hover-capable";
import { cn } from "@/lib/utils";

export type ButtonVariant = "primary" | "secondary" | "ghost" | "outline";
export type ButtonSize = "sm" | "md" | "lg" | "icon";

export interface ButtonProps extends Omit<
  HTMLMotionProps<"button">,
  "children"
> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  pressScale?: number;
  /** Spawn a Material-style ripple from the press point. Off by default. */
  ripple?: boolean;
  children?: ReactNode;
}

export interface ButtonLinkProps extends Omit<
  HTMLMotionProps<"a">,
  "children"
> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  pressScale?: number;
  children?: ReactNode;
}

interface Ripple {
  id: number;
  x: number;
  y: number;
  size: number;
}

const VARIANT_CLASS: Record<ButtonVariant, string> = {
  ghost: "text-muted-foreground hover:text-foreground hover:bg-primary/5",
  outline:
    "border border-border bg-transparent text-foreground hover:bg-primary/5",
  primary: "bg-primary text-primary-foreground hover:bg-primary/90",
  secondary: "border border-border bg-card text-foreground hover:border-border",
};

const SIZE_CLASS: Record<ButtonSize, string> = {
  icon: "h-8 w-8 rounded-lg",
  lg: "h-12 px-6 text-base gap-2 rounded-full",
  md: "h-10 px-5 text-sm gap-2 rounded-full",
  sm: "h-8 px-3 text-xs gap-1.5 rounded-full",
};

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    {
      variant = "primary",
      size = "md",
      pressScale = 0.93,
      ripple = false,
      className,
      children,
      onPointerDown,
      ...rest
    },
    ref
  ) {
    const reduce = useReducedMotion();
    const canHover = useHoverCapable();
    const [ripples, setRipples] = useState<Ripple[]>([]);
    const nextId = useRef(0);

    const handlePointerDown = useCallback(
      (event: PointerEvent<HTMLButtonElement>) => {
        if (ripple && !reduce) {
          const rect = event.currentTarget.getBoundingClientRect();
          const size = Math.max(rect.width, rect.height) * 2;
          const id = nextId.current++;
          setRipples((prev) => [
            ...prev,
            {
              id,
              size,
              x: event.clientX - rect.left,
              y: event.clientY - rect.top,
            },
          ]);
        }
        onPointerDown?.(event);
      },
      [ripple, reduce, onPointerDown]
    );

    return (
      <motion.button
        ref={ref}
        type="button"
        whileTap={reduce ? undefined : { scale: pressScale }}
        whileHover={reduce || !canHover ? undefined : { scale: 1.02 }}
        transition={SPRING_PRESS}
        onPointerDown={handlePointerDown}
        className={cn(
          "inline-flex items-center justify-center font-medium select-none",
          "transition-colors",
          "disabled:pointer-events-none disabled:opacity-50",
          ripple && "relative overflow-hidden",
          VARIANT_CLASS[variant],
          SIZE_CLASS[size],
          className
        )}
        {...rest}
      >
        {ripple && !reduce ? (
          <span className="pointer-events-none absolute inset-0 overflow-hidden rounded-[inherit]">
            <AnimatePresence>
              {ripples.map((r) => (
                <motion.span
                  key={r.id}
                  className="absolute rounded-full bg-current"
                  style={{
                    height: r.size,
                    left: r.x,
                    top: r.y,
                    width: r.size,
                    x: "-50%",
                    y: "-50%",
                  }}
                  initial={{ opacity: 0.3, scale: 0.05 }}
                  animate={{ opacity: 0, scale: 1 }}
                  exit={{ opacity: 0 }}
                  transition={{ duration: 1.6, ease: EASE_OUT }}
                  onAnimationComplete={() =>
                    setRipples((prev) => prev.filter((x) => x.id !== r.id))
                  }
                />
              ))}
            </AnimatePresence>
          </span>
        ) : null}
        {children}
      </motion.button>
    );
  }
);

export const ButtonLink = forwardRef<HTMLAnchorElement, ButtonLinkProps>(
  function ButtonLink(
    {
      variant = "primary",
      size = "md",
      pressScale = 0.93,
      className,
      children,
      ...rest
    },
    ref
  ) {
    const reduce = useReducedMotion();
    const canHover = useHoverCapable();

    return (
      <motion.a
        ref={ref}
        whileTap={reduce ? undefined : { scale: pressScale }}
        whileHover={reduce || !canHover ? undefined : { scale: 1.02 }}
        transition={SPRING_PRESS}
        className={cn(
          "inline-flex items-center justify-center font-medium select-none",
          "transition-colors",
          VARIANT_CLASS[variant],
          SIZE_CLASS[size],
          className
        )}
        {...rest}
      >
        {children}
      </motion.a>
    );
  }
);

"use client";

import {
  AnimatePresence,
  animate,
  motion,
  useReducedMotion,
} from "motion/react";
import { forwardRef, useEffect, useId, useRef, useState } from "react";
import type { InputHTMLAttributes, ReactNode } from "react";

import { cn } from "@/lib/utils";

export interface InputClassNames {
  root?: string;
  label?: string;
  field?: string;
  input?: string;
  leftIcon?: string;
  rightIcon?: string;
  successIcon?: string;
  errorMessage?: string;
}

export interface InputProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "value" | "defaultValue" | "onChange"
> {
  label?: string;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** Truthy error triggers a shake, red border and (if a string) a message. */
  error?: string | boolean;
  /** Reserve one message line so validation does not shift nearby content. */
  reserveErrorLine?: boolean;
  success?: boolean;
  leftIcon?: ReactNode;
  rightIcon?: ReactNode;
  className?: string;
  classNames?: InputClassNames;
}

export const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  {
    label,
    value: valueProp,
    defaultValue,
    onChange,
    onFocus,
    onBlur,
    error,
    reserveErrorLine = false,
    success,
    leftIcon,
    rightIcon,
    className,
    classNames,
    disabled,
    id: idProp,
    type,
    ...rest
  },
  ref
) {
  const reactId = useId();
  const id = idProp ?? reactId;
  const reduce = useReducedMotion();

  const controlled = valueProp !== undefined;
  const [internal, setInternal] = useState(defaultValue ?? "");
  const value = controlled ? (valueProp ?? "") : internal;

  const [focused, setFocused] = useState(false);

  const fieldRef = useRef<HTMLDivElement>(null);

  const hasError = Boolean(error);
  const errorMessage = typeof error === "string" ? error : null;

  // Right edge shows the success check, otherwise the caller's right icon.
  const rightSlot = success ? null : rightIcon;

  // Shake the field when an error appears.
  useEffect(() => {
    if (!fieldRef.current || reduce || !hasError) {
      return;
    }
    animate(
      fieldRef.current,
      { x: [0, -6, 6, -4, 4, -2, 0] },
      { duration: 0.45 }
    );
  }, [hasError, reduce]);

  const handleChange = (next: string) => {
    if (!controlled) {
      setInternal(next);
    }
    onChange?.(next);
  };

  return (
    <div className={cn("flex flex-col gap-1.5", className, classNames?.root)}>
      {label ? (
        <label
          htmlFor={id}
          className={cn(
            "px-1 text-sm font-medium text-foreground",
            classNames?.label
          )}
        >
          {label}
        </label>
      ) : null}

      <div
        ref={fieldRef}
        data-state={
          hasError
            ? "error"
            : success
              ? "success"
              : focused
                ? "focused"
                : "idle"
        }
        className={cn(
          "relative h-11 overflow-hidden rounded-full border transition-colors duration-200",
          "border-border",
          focused && !hasError && "border-foreground/40 ring-2 ring-ring/40",
          hasError && "border-destructive ring-2 ring-destructive/25",
          disabled && "opacity-60",
          classNames?.field
        )}
      >
        {leftIcon ? (
          <span
            className={cn(
              "pointer-events-none absolute left-3 top-1/2 flex -translate-y-1/2 items-center text-muted-foreground [&_svg]:h-4 [&_svg]:w-4",
              classNames?.leftIcon
            )}
          >
            {leftIcon}
          </span>
        ) : null}

        <input
          ref={ref}
          id={id}
          type={type}
          value={value}
          disabled={disabled}
          aria-invalid={hasError || undefined}
          aria-describedby={errorMessage ? `${id}-error` : undefined}
          {...rest}
          onChange={(e) => handleChange(e.target.value)}
          onFocus={(event) => {
            setFocused(true);
            onFocus?.(event);
          }}
          onBlur={(event) => {
            setFocused(false);
            onBlur?.(event);
          }}
          className={cn(
            "peer h-full w-full bg-transparent text-base leading-6 text-foreground caret-foreground outline-none",
            "placeholder:text-muted-foreground/60",
            leftIcon ? "pl-10" : "pl-3.5",
            rightSlot || success ? "pr-10" : "pr-3.5",
            disabled && "cursor-not-allowed",
            classNames?.input
          )}
        />

        {success ? (
          <motion.svg
            viewBox="0 0 24 24"
            fill="none"
            className={cn(
              "absolute right-3.5 top-1/2 h-5 w-5 -translate-y-1/2 text-(--color-success)",
              classNames?.successIcon
            )}
          >
            <motion.path
              d="M5 12.5l4.5 4.5L19 7.5"
              stroke="currentColor"
              strokeWidth={2.5}
              strokeLinecap="round"
              strokeLinejoin="round"
              initial={reduce ? { pathLength: 1 } : { pathLength: 0 }}
              animate={{ pathLength: 1 }}
              transition={{ duration: 0.35, ease: "easeOut" }}
            />
          </motion.svg>
        ) : rightSlot ? (
          <span
            className={cn(
              "absolute right-0 top-0 flex h-full items-center text-muted-foreground [&_button]:grid [&_button]:size-11 [&_button]:place-items-center [&_svg]:h-4 [&_svg]:w-4",
              classNames?.rightIcon
            )}
          >
            {rightSlot}
          </span>
        ) : null}
      </div>

      <div className={reserveErrorLine ? "min-h-4" : "contents"}>
        <AnimatePresence initial={false}>
          {errorMessage ? (
            <motion.p
              id={`${id}-error`}
              role="alert"
              initial={
                reduce
                  ? { opacity: 0 }
                  : { filter: "blur(4px)", opacity: 0, y: -4 }
              }
              animate={{ filter: "blur(0px)", opacity: 1, y: 0 }}
              exit={
                reduce
                  ? { opacity: 0 }
                  : { filter: "blur(4px)", opacity: 0, y: -4 }
              }
              transition={{ duration: 0.2 }}
              className={cn(
                "px-1 text-xs text-destructive",
                classNames?.errorMessage
              )}
            >
              {errorMessage}
            </motion.p>
          ) : null}
        </AnimatePresence>
      </div>
    </div>
  );
});

"use client";

import { motion, MotionConfig, useReducedMotion } from "motion/react";
import {
  createContext,
  useCallback,
  useContext,
  useId,
  useMemo,
  useState,
} from "react";
import type { ReactNode } from "react";

import { SPRING_LAYOUT, SPRING_PRESS } from "@/lib/ease";
import { cn } from "@/lib/utils";

interface RadioCtx {
  value: string;
  setValue: (value: string) => void;
  layoutId: string;
}

const RadioCtx = createContext<RadioCtx | null>(null);

function useRadioGroup() {
  const ctx = useContext(RadioCtx);
  if (!ctx) {
    throw new Error("RadioGroupItem must be used inside <RadioGroup>");
  }
  return ctx;
}

export interface RadioGroupProps {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  children: ReactNode;
  className?: string;
  orientation?: "vertical" | "horizontal";
}

export function RadioGroup({
  value,
  defaultValue = "",
  onValueChange,
  children,
  className,
  orientation = "vertical",
}: RadioGroupProps) {
  const [internal, setInternal] = useState(defaultValue);
  const layoutId = useId();
  const reduce = useReducedMotion();
  const controlled = value !== undefined;
  const current = controlled ? value : internal;
  const setValue = useCallback(
    (next: string) => {
      if (!controlled) {
        setInternal(next);
      }
      onValueChange?.(next);
    },
    [controlled, onValueChange]
  );
  const contextValue = useMemo(
    () => ({ layoutId, setValue, value: current }),
    [current, layoutId, setValue]
  );

  return (
    <MotionConfig transition={reduce ? { duration: 0 } : SPRING_LAYOUT}>
      <RadioCtx.Provider value={contextValue}>
        <div
          role="radiogroup"
          className={cn(
            "flex gap-3",
            orientation === "vertical" ? "flex-col" : "flex-row flex-wrap",
            className
          )}
        >
          {children}
        </div>
      </RadioCtx.Provider>
    </MotionConfig>
  );
}

export interface RadioGroupItemProps {
  value: string;
  label?: string;
  disabled?: boolean;
  className?: string;
  id?: string;
}

export function RadioGroupItem({
  value,
  label,
  disabled,
  className,
  id: idProp,
}: RadioGroupItemProps) {
  const { value: groupValue, setValue, layoutId } = useRadioGroup();
  const autoId = useId();
  const id = idProp ?? autoId;
  const reduce = useReducedMotion();
  const selected = groupValue === value;

  return (
    <label
      htmlFor={id}
      className={cn(
        "inline-flex items-center gap-3",
        disabled ? "cursor-not-allowed" : "cursor-pointer",
        className
      )}
    >
      <motion.button
        id={id}
        type="button"
        role="radio"
        aria-checked={selected}
        disabled={disabled}
        onClick={() => !disabled && setValue(value)}
        whileTap={reduce || disabled ? undefined : { scale: 0.92 }}
        transition={SPRING_PRESS}
        data-state={selected ? "checked" : "unchecked"}
        className={cn(
          "relative inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 outline-none transition-colors duration-200",
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          "disabled:cursor-not-allowed disabled:opacity-60",
          selected
            ? "border-primary"
            : "border-muted-foreground/50 hover:border-muted-foreground"
        )}
      >
        {selected ? (
          <motion.span
            layoutId={layoutId}
            className="absolute inset-1 rounded-full bg-primary"
            transition={reduce ? { duration: 0 } : SPRING_LAYOUT}
          />
        ) : null}
      </motion.button>
      {label ? (
        <span
          className={cn(
            "select-none text-sm text-foreground",
            disabled && "opacity-60"
          )}
        >
          {label}
        </span>
      ) : null}
    </label>
  );
}

// Shared motion tokens. The `--ease-*` custom properties in globals.css carry the same
// curves for CSS-driven motion (view transitions); springs are the canonical physics
// used across components. Strong custom variants — defaults like `ease-in`/`ease-out`
// feel weak.

/** Entrances, exits and content swaps. */
export const EASE_OUT = [0.23, 1, 0.32, 1] as const;

/** Press feedback on buttons and other tappable surfaces. */
export const SPRING_PRESS = {
  damping: 30,
  mass: 0.6,
  stiffness: 500,
} as const;

/** Content swaps — label/icon slots trading places inside a control. */
export const SPRING_SWAP = {
  damping: 30,
  mass: 0.55,
  stiffness: 460,
} as const;

/** Shared-layout glides — pills, indicators and panels morphing between positions. */
export const SPRING_LAYOUT = {
  damping: 32,
  mass: 0.6,
  stiffness: 360,
} as const;

"use client";

import { useEffect, useState } from "react";

/**
 * Returns true only on devices that have a true hover (mouse / trackpad).
 * Touch devices fire phantom `:hover` on tap that sticks until tap-elsewhere
 * — gate hover-only effects (scale lifts, magnetic pulls) behind this.
 */
export function useHoverCapable() {
  const [canHover, setCanHover] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) {
      return;
    }
    const mq = window.matchMedia("(hover: hover) and (pointer: fine)");
    const update = () => setCanHover(mq.matches);
    update();
    mq.addEventListener?.("change", update);
    return () => mq.removeEventListener?.("change", update);
  }, []);

  return canHover;
}
